import React, { useEffect, useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { ArrowLeft, ArrowRight, BarChart3, CalendarDays, Check, ChevronDown, ChevronRight, ChevronUp, Clipboard, Clock3, Crop, Download, Eye, EyeOff, ExternalLink, FileText, FolderKanban, FolderOpen, Grid2X2, Home, Link2, ListTodo, Magnet, Monitor, MoreHorizontal, Pencil, Pin, Plus, RefreshCw, RotateCcw, Search, Settings2, Sparkles, Terminal, TimerReset, Trash2, Undo2, WandSparkles, X, Lock } from 'lucide-react'
import { Toaster, toast } from 'sonner'
import type { AppSettings, BackupEntry, ClipboardRecord, DesktopCategoryRecord, LinkGroupRecord, LinkRecord, NoteRecord, OrganizerEntry, ProjectRecord, SearchFileResult, SystemMetrics, TodoRecord, WidgetPlacement, WorkspaceState } from '../../shared/types'
import './styles.css'

type Page = 'overview' | 'tasks' | 'notes' | 'projects' | 'library' | 'clipboard' | 'organizer' | 'monitor' | 'stats' | 'screenshot' | 'settings'
type IconType = React.ComponentType<{ size?: number; strokeWidth?: number }>

const now = () => new Date().toISOString()
const uid = () => crypto.randomUUID()
const reminderInputValue = (value?: string | null) => {
  if (!value) return ''
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return ''
  const pad = (part: number) => String(part).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`
}
const reminderIsoValue = (value: string) => value ? new Date(value).toISOString() : null
const argbCss = (argb: number, alpha: number) => {
  const value = Number.isFinite(Number(argb)) ? (Number(argb) >>> 0) : 0xffffffff
  return `rgba(${(value >>> 16) & 255}, ${(value >>> 8) & 255}, ${value & 255}, ${Math.max(0, Math.min(1, alpha))})`
}
const argbHex = (argb: number) => `#${(Number(argb) >>> 0).toString(16).slice(-6).padStart(6, '0')}`
const widgetTransparencyClass = 'widget-transparent'
const tagColor = (tag: string) => {
  const colors = [-65536, -16711936, -16776961, -23296, -8388480, -12525360]
  return colors[Math.max(0, tag.length - 1) % colors.length]
}
const withTagPreset = (state: WorkspaceState, tag: string) => {
  const normalized = tag.trim()
  if (!normalized || state.TagPresets.some(item => item.Name.toLowerCase() === normalized.toLowerCase())) return state
  return { ...state, TagPresets: [...state.TagPresets, { Name: normalized, ColorArgb: tagColor(normalized) }] }
}

function starterState(): WorkspaceState {
  const time = now()
  const settings = { MainWindowDisplayName: 'DustDesk', StartHiddenToTray: false, StartWithWindows: false, MainWindowHotKey: 'Ctrl+Shift+K', DesktopWidgetsHotKey: 'Ctrl+Shift+D', ScreenshotHotKey: 'Ctrl+Shift+S', PinScreenshotHotKey: 'F3', ScreenshotFormat: 'png', ScreenshotSaveDirectory: '', ScreenshotDelaySeconds: 0, ScreenshotAfterAction: 'edit', ScreenshotAutoCopy: true, ScreenshotAutoAddToClipboardHistory: true, PinnedImageTopmost: true, PinnedImageOpacityPercent: 100, PinnedImageMouseThrough: false, WidgetOpacityPercent: 86, WidgetBackgroundColorArgb: -1, SearchDesktopFiles: true, SearchAppData: true, SearchStartMenuApps: true, SearchProjectPaths: true, SearchCustomPaths: true, SearchCustomRoots: [], ClipboardMonitoringEnabled: true, DesktopHotKeyWidgetKeys: ['organizer'], LauncherWidgetSnapToEdges: false, LauncherWidgetShowNames: true, LauncherWidgetIconSize: 48, OrganizerWidgetShowNames: false, OrganizerWidgetIconSize: 48, MonitorShowDownload: true, MonitorShowUpload: true, MonitorShowMemory: true, MonitorShowCpu: true, MonitorShowDiskIo: true, MonitorShowDiskSpace: true, MonitorShowPing: true, MonitorShowUptime: true, WorkdayStartMinutes: 540, WorkdayEndMinutes: 1080, MonthlySalary: 0, PaydayDay: 10, CountdownFestivalName: '国庆节', CountdownFestivalMonth: 10, CountdownFestivalDay: 1, WidgetPlacements: {}, NoteWidgetPlacements: [], OrganizerGroupWidgetPlacements: [], WidgetLayoutPresets: {} } as AppSettings
  return { SchemaVersion: 2, LegacyImportCompleted: false, QuickNote: '', Settings: settings, Todos: [], TagPresets: [], Notes: [{ Id: uid(), Title: '快速便签', Text: '', ColorArgb: -411768, FontColorArgb: -1385444, FontSize: 14, FontBold: false, BackgroundImageFileName: '', ImageOnly: false, CreatedAt: time, UpdatedAt: time }], Projects: [], Launchers: [], LinkGroups: [{ Id: uid(), Name: '常用', Links: [] }], ClipboardHistory: [], DesktopCategories: ['工作', '开发', '工具', '文件'].map(Name => ({ Id: uid(), Name, IsCollapsed: false, ItemPaths: [] })) }
}

const nav: { id: Page; label: string; icon: IconType }[] = [
  { id: 'overview', label: '概览', icon: Home }, { id: 'tasks', label: '任务', icon: ListTodo }, { id: 'notes', label: '便签', icon: FileText }, { id: 'projects', label: '项目', icon: FolderKanban }, { id: 'library', label: '资源库', icon: Link2 }, { id: 'clipboard', label: '剪贴板', icon: Clipboard }, { id: 'organizer', label: '桌面收纳', icon: Grid2X2 }, { id: 'screenshot', label: '截图编辑', icon: Crop }, { id: 'monitor', label: '系统检测', icon: Monitor }, { id: 'stats', label: '统计分析', icon: BarChart3 }
]

const pageDescriptions: Record<Page, string> = {
  overview: '把注意力留给真正重要的事情。',
  tasks: '把今天要完成的事情放在一个清晰的队列里。',
  notes: '把灵感、会议记录和临时信息留在手边。',
  projects: '把阶段、进度和下一步行动放在同一张地图上。',
  library: '按分类整理常用链接、应用和文件入口。',
  clipboard: '最近复制的文字和图片会在这里暂存。',
  organizer: '将桌面文件按分类整理，支持智能预览、冲突保护和撤销。',
  screenshot: '捕获屏幕内容，快速标记并保存。',
  monitor: '查看当前设备的资源状态和工作环境。',
  stats: '用简单的数字回顾工作区的积累。',
  settings: '让 DustDesk 适应你的工作方式。'
}

function App() {
  const [state, setState] = useState<WorkspaceState>(starterState)
  const [page, setPage] = useState<Page>('overview')
  const [loaded, setLoaded] = useState(false)
  const [query, setQuery] = useState('')
  const [theme, setTheme] = useState<'light' | 'dark'>('light')
  const [dataPath, setDataPath] = useState('')
  const [fileResults, setFileResults] = useState<SearchFileResult[]>([])

  useEffect(() => { void Promise.all([window.dustdesk.loadWorkspace(), window.dustdesk.getDataLocation()]).then(([next, path]) => { setState({ ...starterState(), ...next, Settings: { ...starterState().Settings, ...next.Settings } }); setDataPath(path); setLoaded(true) }).catch(() => { setLoaded(true); toast.error('无法读取工作区，已使用空白工作区') }) }, [])
  useEffect(() => { document.documentElement.dataset.theme = theme }, [theme])
  useEffect(() => window.dustdesk.onClipboardChanged(record => { setState(current => { if (current.ClipboardHistory.some(item => item.ImageSha256 === record.ImageSha256)) return current; const next = { ...current, ClipboardHistory: [record, ...current.ClipboardHistory].slice(0, 200) }; void window.dustdesk.saveWorkspace(next); return next }) }), [])
  useEffect(() => { const handler = (event: KeyboardEvent) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); document.getElementById('global-search')?.focus() } }; window.addEventListener('keydown', handler); return () => window.removeEventListener('keydown', handler) }, [])
  useEffect(() => { const text = query.trim(); if (text.length < 2) { setFileResults([]); return }; const timer = window.setTimeout(() => { void window.dustdesk.searchFiles(text).then(setFileResults).catch(() => setFileResults([])) }, 220); return () => window.clearTimeout(timer) }, [query])

  const persist = async (next: WorkspaceState, message = '已保存') => { setState(next); try { await window.dustdesk.saveWorkspace(next); toast.success(message) } catch { toast.error('保存失败，请重试') } }
  const update = <K extends keyof WorkspaceState>(key: K, value: WorkspaceState[K], message?: string) => void persist({ ...state, [key]: value }, message)
  const pageTitle = page === 'overview' ? '概览' : page === 'library' ? '资源库' : nav.find(item => item.id === page)?.label ?? '设置'
  const searchResults = useMemo(() => {
    const text = query.trim().toLowerCase(); if (!text) return []
    const match = (...values: string[]) => values.some(value => value.toLowerCase().includes(text))
    const projectResults = state.Projects.flatMap(project => {
      const results = match(project.Name, project.ProjectPath) ? [{ title: project.Name, meta: '项目', page: 'projects' as Page }] : []
      for (const phase of project.Phases) {
        if (match(phase.Title, phase.ProjectPath)) results.push({ title: phase.Title, meta: '项目阶段', page: 'projects' as Page })
        for (const subtask of phase.Subtasks) if (match(subtask.Title, subtask.FilePath)) results.push({ title: subtask.Title, meta: '项目子事项', page: 'projects' as Page })
      }
      return results
    })
    return [...state.Todos.filter(item => match(item.Title, item.Tag, item.Note)).map(item => ({ title: item.Title, meta: '任务', page: 'tasks' as Page })), ...state.Notes.filter(item => match(item.Title, item.Text)).map(item => ({ title: item.Title, meta: '便签', page: 'notes' as Page })), ...projectResults, ...state.LinkGroups.flatMap(group => group.Links.filter(link => match(link.Name, link.Url, link.Note, group.Name)).map(link => ({ title: link.Name, meta: '链接', page: 'library' as Page }))), ...state.Launchers.filter(item => match(item.Name, item.Path)).map(item => ({ title: item.Name, meta: '启动器', page: 'library' as Page })), ...state.DesktopCategories.filter(item => match(item.Name, ...item.ItemPaths)).map(item => ({ title: item.Name, meta: '桌面分类', page: 'organizer' as Page })), ...fileResults.map(item => ({ title: item.Name, meta: item.IsDirectory ? '文件夹' : '文件', path: item.Path }))].slice(0, 12)
  }, [query, state, fileResults])
  const handleSearchKey = (event: React.KeyboardEvent<HTMLInputElement>) => { if (event.key !== 'Enter') return; const value = query.trim(); const match = /^(todo|task|note|clip|open)\s*(.*)$/i.exec(value); if (!match) return; const command = match[1].toLowerCase(); const argument = match[2].trim(); if (command === 'clip') { setPage('clipboard'); setQuery(''); return }; if (command === 'open' && argument) { void window.dustdesk.openPath(argument); setQuery(''); return }; if (command === 'todo' || command === 'task') { if (argument) void update('Todos', [...state.Todos, { Id: uid(), Title: argument, Tag: '', Note: '', IsCompleted: false, CreatedAt: now(), ReminderRepeat: 'None' }], '任务已创建'); setPage('tasks'); setQuery(''); return }; if (command === 'note') { const note: NoteRecord = { Id: uid(), Title: argument || '新便签', Text: '', ColorArgb: -411768, FontColorArgb: -1385444, FontSize: 14, FontBold: false, BackgroundImageFileName: '', ImageOnly: false, CreatedAt: now(), UpdatedAt: now() }; void update('Notes', [note, ...state.Notes], '便签已创建'); setPage('notes'); setQuery('') } }

  if (!loaded) return <div className="boot"><Sparkles size={22} /><span>正在打开 DustDesk</span></div>
  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark">D</div><div><strong>DustDesk</strong><span>本地工作台</span></div></div>
      <div className="workspace-chip"><span className="status-dot" />{state.Settings.MainWindowDisplayName || 'DustDesk'}<ChevronRight size={14} /></div>
      <nav className="nav-list">{nav.map(item => <button key={item.id} className={`nav-item ${page === item.id ? 'active' : ''}`} onClick={() => setPage(item.id)}><item.icon size={17} strokeWidth={1.8} /><span>{item.label}</span>{item.id === 'tasks' && state.Todos.filter(todo => !todo.IsCompleted).length > 0 ? <em>{state.Todos.filter(todo => !todo.IsCompleted).length}</em> : null}</button>)}</nav>
      <div className="sidebar-bottom"><button className={`nav-item ${page === 'settings' ? 'active' : ''}`} onClick={() => setPage('settings')}><Settings2 size={17} strokeWidth={1.8} /><span>设置</span></button><div className="sidebar-meta"><span>Electron 重构预览</span><span className="version">v2.0</span></div></div>
    </aside>
    <main className="main-area">
      <header className="topbar"><div className="topbar-title"><p className="eyebrow">{new Intl.DateTimeFormat('zh-CN', { weekday: 'long', month: 'long', day: 'numeric' }).format(new Date())}</p><h1>{pageTitle}</h1><p className="topbar-description">{pageDescriptions[page]}</p></div><div className="top-actions"><div className="search-wrap"><Search size={16} /><input id="global-search" value={query} onChange={event => setQuery(event.target.value)} onKeyDown={handleSearchKey} placeholder="搜索任务、便签、项目和文件" /><kbd>⌘ K</kbd>{query && <div className="search-popover">{searchResults.length ? searchResults.map(result => <button key={`${result.meta}-${result.title}`} onClick={() => { if ('path' in result) void window.dustdesk.openPath(result.path); else setPage(result.page); setQuery('') }}><span>{result.title}</span><small>{result.meta}</small></button>) : <div className="search-empty">没有匹配结果</div>}</div>}</div><button className="icon-button" title="切换主题" onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}><Monitor size={17} /></button><button className="avatar">DD</button></div></header>
      <section className="content"><div className="content-inner">{page === 'overview' && <Overview state={state} onNavigate={setPage} onAdd={title => update('Todos', [...state.Todos, { Id: uid(), Title: title, Tag: '', Note: '', IsCompleted: false, CreatedAt: now(), ReminderRepeat: 'None' }], '任务已创建')} />}{page === 'tasks' && <Tasks state={state} persist={persist} />}{page === 'notes' && <Notes state={state} persist={persist} />}{page === 'projects' && <Projects state={state} persist={persist} />}{page === 'library' && <LibraryV2 state={state} persist={persist} />}{page === 'clipboard' && <ClipboardPage state={state} persist={persist} />}{page === 'organizer' && <Organizer state={state} persist={persist} />}{page === 'screenshot' && <ScreenshotPage />}{page === 'monitor' && <MonitorPage state={state} persist={persist} />}{page === 'stats' && <StatsPage state={state} />}{page === 'settings' && <Settings state={state} persist={persist} path={dataPath} theme={theme} setTheme={setTheme} />}</div></section>
    </main><Toaster position="bottom-right" duration={2200} />
  </div>
}

function PageHeader({ action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) { return action ? <div className="page-header page-actions-only">{action}</div> : null }
function Panel({ children, className = '' }: { children: React.ReactNode; className?: string }) { return <section className={`panel ${className}`}>{children}</section> }
function Empty({ icon: Icon, title, description, action }: { icon: IconType; title: string; description: string; action?: React.ReactNode }) { return <div className="empty"><div className="empty-icon"><Icon size={20} /></div><strong>{title}</strong><span>{description}</span>{action}</div> }

function Overview({ state, onNavigate, onAdd }: { state: WorkspaceState; onNavigate: (page: Page) => void; onAdd: (title: string) => void }) {
  const openTodos = state.Todos.filter(todo => !todo.IsCompleted); const completed = state.Todos.filter(todo => todo.IsCompleted).length; const [title, setTitle] = useState('')
  return <><PageHeader eyebrow="今天的工作台" title={`早上好，${state.Settings.MainWindowDisplayName || 'DustDesk'}`} description="把注意力留给真正重要的事情。" action={<button className="primary-button" onClick={() => onNavigate('tasks')}><ListTodo size={16} />查看任务</button>} /><div className="metrics"><div className="metric"><span>待完成</span><strong>{openTodos.length}</strong><small>件任务</small></div><div className="metric"><span>今日完成</span><strong>{completed}</strong><small>件任务</small></div><div className="metric"><span>便签</span><strong>{state.Notes.length}</strong><small>条记录</small></div><div className="metric accent"><span>工作日进度</span><strong>{Math.round(((new Date().getHours() * 60 + new Date().getMinutes()) - state.Settings.WorkdayStartMinutes) / Math.max(1, state.Settings.WorkdayEndMinutes - state.Settings.WorkdayStartMinutes) * 100)}%</strong><small>按当前时间估算</small></div></div><div className="overview-grid"><Panel><div className="panel-heading"><div><span className="section-kicker">Focus</span><h3>今天要做什么</h3></div><button className="text-button" onClick={() => onNavigate('tasks')}>全部任务 <ChevronRight size={15} /></button></div><div className="quick-add"><input value={title} onChange={event => setTitle(event.target.value)} onKeyDown={event => { if (event.key === 'Enter' && title.trim()) { onAdd(title.trim()); setTitle('') } }} placeholder="添加一项任务..." /><button className="round-button" title="添加任务" onClick={() => { if (title.trim()) { onAdd(title.trim()); setTitle('') } }}><Plus size={17} /></button></div><div className="todo-list compact">{openTodos.slice(0, 5).map(todo => <div className="todo-row" key={todo.Id}><span className="todo-check" /><span>{todo.Title}</span>{todo.Tag && <small>{todo.Tag}</small>}</div>)}{openTodos.length === 0 && <Empty icon={Check} title="今天没有未完成任务" description="可以把时间留给更重要的事。" />}</div></Panel><Panel><div className="panel-heading"><div><span className="section-kicker">Quick note</span><h3>快速记录</h3></div><button className="icon-button subtle" title="打开便签" onClick={() => onNavigate('notes')}><ExternalLink size={16} /></button></div><textarea className="quick-note" defaultValue={state.QuickNote} placeholder="把刚刚想到的事记下来..." onBlur={event => { const next = { ...state, QuickNote: event.target.value }; void window.dustdesk.saveWorkspace(next) }} /><div className="panel-foot"><span><Clock3 size={14} />自动保存</span><span>{state.Notes.length} 条便签</span></div></Panel></div></>
}

function Tasks({ state, persist }: { state: WorkspaceState; persist: (next: WorkspaceState, message?: string) => Promise<void> }) {
  const [filter, setFilter] = useState<'all' | 'open' | 'done' | 'overdue'>('open'); const [title, setTitle] = useState(''); const [tag, setTag] = useState(''); const [selected, setSelected] = useState<string | null>(null); const [selectedDate, setSelectedDate] = useState(() => new Date())
  const dateKey = (value: Date) => `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, '0')}-${String(value.getDate()).padStart(2, '0')}`; const selectedKey = dateKey(selectedDate)
  const dateTodos = state.Todos.filter(todo => dateKey(new Date(todo.CreatedAt)) === selectedKey)
  const todos = dateTodos.filter(todo => filter === 'all' || filter === 'open' && !todo.IsCompleted || filter === 'done' && todo.IsCompleted || filter === 'overdue' && !todo.IsCompleted && !!todo.ReminderAt && new Date(todo.ReminderAt) < new Date() && !todo.ReminderNotifiedAt)
  const add = () => { if (!title.trim()) return; const created = new Date(selectedDate); const current = new Date(); created.setHours(current.getHours(), current.getMinutes(), current.getSeconds(), current.getMilliseconds()); const next = withTagPreset({ ...state, Todos: [...state.Todos, { Id: uid(), Title: title.trim(), Tag: tag.trim(), Note: '', IsCompleted: false, CreatedAt: created.toISOString(), ReminderAt: null, ReminderNotifiedAt: null, ReminderRepeat: 'None' }] }, tag); void persist(next, '任务已创建'); setTitle(''); setTag('') }
  const toggle = (id: string) => void persist({ ...state, Todos: state.Todos.map(todo => todo.Id === id ? { ...todo, IsCompleted: !todo.IsCompleted } : todo) }, '任务状态已更新')
  const remove = (id: string) => void persist({ ...state, Todos: state.Todos.filter(todo => todo.Id !== id) }, '任务已删除')
  const setTodo = (id: string, changes: Partial<TodoRecord>, message = '任务已保存') => { const next = withTagPreset({ ...state, Todos: state.Todos.map(item => item.Id === id ? { ...item, ...changes, ReminderNotifiedAt: changes.ReminderAt !== undefined ? null : item.ReminderNotifiedAt } : item) }, typeof changes.Tag === 'string' ? changes.Tag : ''); void persist(next, message) }
  const snooze = (todo: TodoRecord, minutes: number) => setTodo(todo.Id, { ReminderAt: new Date(Date.now() + minutes * 60_000).toISOString(), ReminderNotifiedAt: null }, `已推迟 ${minutes} 分钟`)
  return <><PageHeader eyebrow="Tasks" title="任务" description="把今天要完成的事情放在一个清晰的队列里。" action={<div className="task-toolbar"><div className="date-stepper"><button className="icon-button subtle" title="前一天" onClick={() => setSelectedDate(value => new Date(value.getTime() - 86400000))}><ArrowLeft size={14} /></button><span><CalendarDays size={14} />{selectedDate.toLocaleDateString('zh-CN', { month: 'long', day: 'numeric' })}</span><button className="icon-button subtle" title="后一天" onClick={() => setSelectedDate(value => new Date(value.getTime() + 86400000))}><ArrowRight size={14} /></button><button className="mini-button" onClick={() => setSelectedDate(new Date())}>今天</button></div><div className="segmented">{(['open', 'all', 'done', 'overdue'] as const).map(item => <button key={item} className={filter === item ? 'selected' : ''} onClick={() => setFilter(item)}>{item === 'open' ? '未完成' : item === 'all' ? '全部' : item === 'done' ? '已完成' : '逾期'}</button>)}</div></div>} /><Panel><div className="quick-add wide"><input value={title} onChange={event => setTitle(event.target.value)} onKeyDown={event => event.key === 'Enter' && add()} placeholder="添加一个任务，按 Enter 保存" autoFocus /><input value={tag} onChange={event => setTag(event.target.value)} list="todo-tags" placeholder="标签（可选）" /><datalist id="todo-tags">{state.TagPresets.map(item => <option key={item.Name} value={item.Name} />)}</datalist><button className="primary-button" onClick={add}><Plus size={16} />添加任务</button></div><div className="todo-list">{todos.map(todo => <div className={`todo-row detailed ${todo.IsCompleted ? 'completed' : ''}`} key={todo.Id}><button className={`todo-check ${todo.IsCompleted ? 'checked' : ''}`} onClick={() => toggle(todo.Id)} title={todo.IsCompleted ? '标记为未完成' : '标记为完成'}>{todo.IsCompleted && <Check size={13} />}</button><div className="todo-main"><span>{todo.Title}</span><small>{todo.Tag || '未分类'} · {new Date(todo.CreatedAt).toLocaleDateString('zh-CN')}{todo.ReminderAt ? ` · 提醒 ${new Date(todo.ReminderAt).toLocaleString('zh-CN')}` : ''}</small></div><button className="icon-button subtle" title="编辑任务" onClick={() => setSelected(selected === todo.Id ? null : todo.Id)}><Pencil size={15} /></button><button className="icon-button danger" title="删除任务" onClick={() => remove(todo.Id)}><Trash2 size={15} /></button>{selected === todo.Id && <div className="task-editor"><input className="inline-note" defaultValue={todo.Tag} list="todo-tags" placeholder="标签" onBlur={event => setTodo(todo.Id, { Tag: event.target.value }, '标签已保存')} /><input className="inline-note" defaultValue={todo.Note} placeholder="任务备注" onBlur={event => setTodo(todo.Id, { Note: event.target.value }, '备注已保存')} /><label>提醒时间<input type="datetime-local" value={reminderInputValue(todo.ReminderAt)} onChange={event => setTodo(todo.Id, { ReminderAt: reminderIsoValue(event.target.value), ReminderRepeat: event.target.value ? todo.ReminderRepeat : 'None' })} /></label><label>重复<select value={todo.ReminderRepeat} disabled={!todo.ReminderAt} onChange={event => setTodo(todo.Id, { ReminderRepeat: event.target.value as TodoRecord['ReminderRepeat'] })}><option value="None">不重复</option><option value="Daily">每天</option><option value="Weekdays">工作日</option><option value="Weekly">每周</option></select></label>{todo.ReminderAt && <div className="task-snooze"><button className="text-button" onClick={() => snooze(todo, 15)}>15 分钟</button><button className="text-button" onClick={() => snooze(todo, 30)}>30 分钟</button><button className="text-button" onClick={() => snooze(todo, 60)}>1 小时</button><button className="text-button" onClick={() => snooze(todo, 1440)}>明天</button><button className="text-button" onClick={() => setTodo(todo.Id, { ReminderAt: null, ReminderRepeat: 'None', ReminderNotifiedAt: null }, '提醒已清除')}>清除提醒</button></div>}</div>}</div>)}{todos.length === 0 && <Empty icon={Check} title="这里还没有任务" description="添加一项任务，开始组织今天。" />}</div></Panel></>
}

